def max_energy(beads):
    # Initialize a dictionary to store the maximum energy for each prefix of the necklace
    prefix_max = {0: 0, 1: beads[0]}
    # Initialize a dictionary to store the maximum energy for each suffix of the necklace
    suffix_max = {0: 0, 1: beads[-1]}
    # Iterate over the rest of the beads
    for i in range(2, len(beads)):
        # Update the prefix maximum energy
        prefix_max[i] = max(prefix_max[i - 1], prefix_max[i - 2] + beads[i - 1] * beads[i])
        # Update the suffix maximum energy
        suffix_max[i] = max(suffix_max[i - 1], suffix_max[i - 2] + beads[-i] * beads[-i - 1])
    # Return the maximum energy obtainable by merging all beads
    return max(prefix_max[len(beads) - 1], suffix_max[len(beads) - 1])
