def decode(encoded, original, message):
    encoding_dict = {}
    decoding_dict = {}
    for i in range(len(encoded)):
        if encoded[i] not in encoding_dict:
            encoding_dict[encoded[i]] = original[i]
        else:
            if encoding_dict[encoded[i]] != original[i]:
                return "Failed"
    for key, value in encoding_dict.items():
        decoding_dict[value] = key
    decoded_message = ""
    for char in message:
        if char in decoding_dict:
            decoded_message += decoding_dict[char]
        else:
            return "Failed"
    return decoded_message
[/PYTHON]

