def preorder_traversal(inorder, postorder):
    inorder_idx = {c: i for i, c in enumerate(inorder)}
    postorder_idx = {c: i for i, c in enumerate(postorder)}
    inorder_len = len(inorder)
    postorder_len = len(postorder)

    def helper(inorder_start, inorder_end, postorder_start, postorder_end):
        if inorder_start > inorder_end or postorder_start > postorder_end:
            return ''
        if inorder_start == inorder_end:
            return inorder[inorder_start]
        root = postorder[postorder_end]
        inorder_root_idx = inorder_idx[root]
        left_len = inorder_root_idx - inorder_start
        right_len = inorder_end - inorder_root_idx
        left_subtree = helper(inorder_start, inorder_root_idx - 1, postorder_start, postorder_start + left_len - 1)
        right_subtree = helper(inorder_root_idx + 1, inorder_end, postorder_end - right_len, postorder_end - 1)
        return left_subtree + root + right_subtree

    return helper(0, inorder_len - 1, 0, postorder_len - 1)
[/PYTHON]

