def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    dp = [1] * (m + 1)
    for i in range(1, n + 1):
        for j in range(a[i - 1], m + 1):
            dp[j] += dp[j - a[i - 1]]
            dp[j] %= MOD
    return dp[m]
